events.raw:
{
  "understanding": "Kestrel Genetic Medicine, a private health-care provider established in Subregion A1, will make a one-off encrypted upload from A1 to Harrow Inherited Cardiac Clinic in Region B. The upload contains one identified adult patient's name, date of birth, clinic reference number, genetic test report, ECG summary, and referral letter for a treatment-related second opinion. The information will be accessed and stored in both A1 and B. Harrow will review the material, conduct one video consultation, and retain the referral in its own clinical record; no onward transfer is proposed. The patient requested the referral and gave explicit consent after being informed of the absence of recognition or safeguards for the transfer.",
  "engagements": [
    {
      "corpus": "region_a",
      "engaged": true,
      "reason": "The sender is established in Subregion A1, the patient is an adult resident of A1, and the identified genetic and health information is stored and accessed in A1. The transaction is also an outward transfer from Region A to Region B, so Region A's territorial, health-information, sensitive-information, consent, impact-assessment, and outward-transfer provisions could plausibly apply.",
      "facts": [
        {
          "fact_id": "f_12d62771fdeb",
          "path": "",
          "quote": ""
        },
        {
          "fact_id": "f_db2a7b298ba6",
          "path": "",
          "quote": ""
        },
        {
          "fact_id": "f_6a3e2263dd33",
          "path": "",
          "quote": ""
